  1→//go:build e2e
  2→
  3→package agents
  4→
  5→import (
  6→	"context"
  7→	"fmt"
  8→	"os"
  9→	"os/exec"
 10→	"strings"
 11→	"time"
 12→)
 13→
 14→func init() {
 15→	if env := os.Getenv("E2E_AGENT"); env != "" && env != "kiro" {
 16→		return
 17→	}
 18→	if _, err := exec.LookPath("kiro-cli"); err != nil {
 19→		return
 20→	}
 21→	Register(&Kiro{})
 22→	// Kiro uses Amazon Q API which may have rate limits
 23→	RegisterGate("kiro", 1)
 24→}
 25→
 26→// Kiro implements the Agent interface for Amazon's Kiro CLI.
 27→type Kiro struct{}
 28→
 29→func (k *Kiro) Name() string               { return "kiro" }
 30→func (k *Kiro) Binary() string             { return "kiro-cli" }
 31→func (k *Kiro) EntireAgent() string        { return "kiro" }
 32→func (k *Kiro) PromptPattern() string      { return `!>` }
 33→func (k *Kiro) TimeoutMultiplier() float64 { return 1.5 }
 34→
 35→func (k *Kiro) IsTransientError(out Output, _ error) bool {
 36→	combined := out.Stdout + out.Stderr
 37→	for _, p := range []string{"overloaded", "rate limit", "503", "529", "throttl"} {
 38→		if strings.Contains(strings.ToLower(combined), p) {
 39→			return true
 40→		}
 41→	}
 42→	return false
 43→}
 44→
 45→func (k *Kiro) Bootstrap() error {
 46→	// kiro-cli uses Amazon Q / Builder ID auth.
 47→	// On CI, ensure the user is logged in; locally, auth is handled by the desktop app.
 48→	if os.Getenv("CI") == "" {
 49→		return nil
 50→	}
 51→	// Verify login status — fail fast if not authenticated.
 52→	ctx, cancel := context.WithTimeout(context.Background(), 10*time.Second)
 53→	defer cancel()
 54→	cmd := exec.CommandContext(ctx, "kiro-cli", "whoami")
 55→	if out, err := cmd.CombinedOutput(); err != nil {
 56→		return fmt.Errorf("kiro-cli auth check failed (run `kiro-cli login`): %s", out)
 57→	}
 58→	return nil
 59→}
 60→
 61→func (k *Kiro) RunPrompt(ctx context.Context, dir string, prompt string, opts ...Option) (Output, error) {
 62→	cfg := &runConfig{}
 63→	for _, o := range opts {
 64→		o(cfg)
 65→	}
 66→
 67→	// kiro-cli --no-interactive mode does not fire agent hooks, so we must
 68→	// use interactive (tmux) mode and send the prompt through the TUI.
 69→	timeout := 2 * time.Minute
 70→	if cfg.PromptTimeout > 0 {
 71→		timeout = cfg.PromptTimeout
 72→	}
 73→
 74→	// --agent entire activates the agent profile that contains our hooks
 75→	args := []string{"chat", "-a", "--agent", "entire"}
 76→	if cfg.Model != "" {
 77→		args = append(args, "--model", cfg.Model)
 78→	}
 79→
 80→	name := fmt.Sprintf("kiro-run-%d", time.Now().UnixNano())
 81→	s, err := NewTmuxSession(name, dir, nil, k.Binary(), args...)
 82→	if err != nil {
 83→		return Output{}, fmt.Errorf("starting kiro session: %w", err)
 84→	}
 85→	defer func() { _ = s.Close() }()
 86→
 87→	// Wait for initial prompt — kiro-cli TUI shows "!>" in trust-all mode
 88→	if _, err := s.WaitFor(k.PromptPattern(), 30*time.Second); err != nil {
 89→		content := s.Capture()
 90→		return Output{
 91→			Command: k.Binary() + " " + strings.Join(args, " "),
 92→			Stderr:  content,
 93→		}, fmt.Errorf("waiting for kiro startup: %w", err)
 94→	}
 95→	s.stableAtSend = ""
 96→
 97→	// Send the prompt
 98→	if err := s.Send(prompt); err != nil {
 99→		return Output{}, fmt.Errorf("sending prompt to kiro: %w", err)
100→	}
101→
102→	// Wait for "Credits:" which only appears after the agent finishes a response.
103→	// More reliable than PromptPattern for single-prompt mode since it uniquely
104→	// identifies response completion without needing to distinguish echoed input.
105→	content, err := s.WaitFor(`Credits:`, timeout)
106→	exitCode := 0
107→	if err != nil {
108→		exitCode = -1
109→	}
110→
111→	return Output{
112→		Command:  k.Binary() + " " + strings.Join(args, " ") + " " + fmt.Sprintf("%q", prompt),
113→		Stdout:   content,
114→		ExitCode: exitCode,
115→	}, err
116→}
117→
118→func (k *Kiro) StartSession(ctx context.Context, dir string) (Session, error) {
119→	name := fmt.Sprintf("kiro-test-%d", time.Now().UnixNano())
120→	s, err := NewTmuxSession(name, dir, nil, k.Binary(), "chat", "-a", "--agent", "entire")
121→	if err != nil {
122→		return nil, err
123→	}
124→
125→	// Wait for the prompt indicator — kiro-cli TUI shows "!>" in trust-all mode
126→	if _, err := s.WaitFor(k.PromptPattern(), 15*time.Second); err != nil {
127→		_ = s.Close()
128→		return nil, fmt.Errorf("waiting for kiro startup prompt: %w", err)
129→	}
130→	s.stableAtSend = ""
131→
132→	return &KiroSession{TmuxSession: s}, nil
133→}
134→
135→// KiroSession wraps TmuxSession for Kiro's interactive sessions.
136→// After Send, WaitFor uses an end-of-line pattern to avoid matching
137→// the echoed "!>" prompt in the input line.
138→type KiroSession struct {
139→	*TmuxSession
140→}
141→
142→func (s *KiroSession) WaitFor(pattern string, timeout time.Duration) (string, error) {
143→	// For initial waits (before any Send), use the original pattern ("!>").
144→	if s.stableAtSend == "" {
145→		return s.TmuxSession.WaitFor(pattern, timeout)
146→	}
147→	// After a Send, the echoed input line contains "!>" with text after it
148→	// (e.g., "[entire] 3% !> now commit it"). The real prompt has "!>" at
149→	// end-of-line (e.g., "[entire] 3% !>"). Match only the latter.
150→	return s.TmuxSession.WaitFor(`(?m)!>\s*$`, timeout)
151→}
